import {TELEGRAM_BOT_URL} from './config.js';
import {enrich,recoveries,parseContract,contractText,monthStats} from './stage-data.js';
import{seed,rules,check,exposure,csv}from'./engine.js';
let s;try{s=(JSON.parse(localStorage.getItem('tejam.v3'))?.invoiceChecks||JSON.parse(localStorage.getItem('tejam-v2')))}catch{}s=enrich(s||seed());let page=location.hash==='#branches'?'branches':'checks',query='',filter='all';const $=q=>document.querySelector(q),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=x=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(x),compact=x=>x>=1e6?(x/1e6).toLocaleString('ru-RU',{maximumFractionDigits:1})+' млн':money(x),vn=id=>s.vendors.find(v=>v.id===id)?.name||id,bn=id=>s.branches.find(b=>b.id===id)?.name||id;
const nav=[['overview','◫','Обзор'],['checks','◇','Центр проверок'],['documents','▤','Документы'],['contracts','▧','Договоры'],['recovery','↶','Возврат средств'],['vendors','♧','Поставщики'],['branches','▦','Точки'],['audit','◷','Журнал решений'],['rules','⚙','Правила контроля']];function persist(){localStorage.setItem('tejam.v3',JSON.stringify({...JSON.parse(localStorage.getItem('tejam.v3')||'{}'),invoiceChecks:s}))}function log(action,target,note=''){s.log.unshift({date:new Date().toLocaleString('ru-RU'),action,target,note});persist()}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}function btn(text,action,cls=''){return`<button class="btn ${cls}" data-action="${action}">${text}</button>`}function tag(f){return`<span class="tag ${f.status==='open'?f.severity:f.status}">${f.status==='confirmed'?'Подтверждено':f.status==='dismissed'?'Снято':f.status==='requested'?'Запрошены данные':f.severity==='high'?'Высокий риск':f.severity==='low'?'Напоминание':'Проверить'}</span>`}function table(fs){return`<div class="tablewrap"><table><thead><tr><th>ДОКУМЕНТ / ПОСТАВЩИК</th><th>СИГНАЛ</th><th>СУММА СЧЁТА</th><th>СТАТУС</th><th></th></tr></thead><tbody>${fs.map(f=>{let d=s.invoices.find(x=>x.id===f.invoice);return`<tr><td><strong>${esc(vn(d.vendor))}</strong><small>${esc(d.id)} · ${esc(bn(d.branch))}</small></td><td>${esc(f.title)}</td><td>${money(d.amount)} ${esc(d.currency)}</td><td>${tag(f)}</td><td><button class="textbtn" data-case="${esc(f.id)}">Разобрать ↗</button></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">Нет сигналов по выбранным условиям</td></tr>'}</tbody></table></div>`}
function render(){let fs=check(s),open=fs.filter(f=>f.status==='open');let title=nav.find(n=>n[0]===page)?.[2]||({upload:'Новая проверка',demo:'Демонстрация',about:'О проекте'})[page];$('#app').innerHTML=`<aside><div class="logo"><b>t</b><span>tejam</span><small>AI</small></div><div class="workspace">▣ <div><b>Демо-проверки</b><small>Контроль операционных расходов</small></div></div><p class="navlabel">РАБОЧЕЕ ПРОСТРАНСТВО</p><nav class="nav">${nav.map(n=>`<button data-page="${n[0]}" class="${page===n[0]?'active':''}"><em>${icon(n[0])}</em><span>${n[2]}</span></button>`).join('')}</nav><div class="sidefoot"><div class="sidepromo"><b>От данных к решению</b><br>Три шага, чтобы увидеть Tejam в деле.<button data-page="demo">Запустить демо ↗</button></div><button class="textbtn" data-page="about" style="padding:15px 0">Как устроен Tejam</button><div class="profile"><div class="avatar">Д</div><div><b>Динара</b><small>Демонстрационный профиль</small></div></div></div></aside><main><header><div><button class="mobilemenu" data-action="menu" aria-label="Открыть меню">☰</button>Рабочее пространство <span style="margin:0 10px">/</span> ${title}</div><div class="toptools"><span class="live"><i class="dot"></i> Демо · симуляция</span><button id="theme" class="themebtn" aria-label="Переключить тему">${icon('theme')}</button></div></header><div class="content"><div class="pagehead"><div><h1>${page==='overview'?'Деньги под контролем':title}</h1><div class="sub">${page==='overview'?'Вся картина расходов. Каждая деталь имеет значение.':'Tejam AI · Контроль с понятными доказательствами'}</div></div><div class="actions">${btn('↓ Экспорт','export')}${btn('＋ Новая проверка','upload','primary')}</div></div>${content(fs,open)}<div class="footer"><span>TEJAM AI · HACKATHON EDITION</span><span>Локальное демо · ${s.invoices.length} счетов · ${s.enabled.length} правил · без подключения к бизнесу</span></div></div></main>`;bind();stageBind()}
function legacyContent(fs,open){if(page==='overview'){let totals=s.contracts.map(c=>s.invoices.filter(d=>d.contract===c.id&&d.currency==='UZS').reduce((a,d)=>a+d.amount,0)),other=s.invoices.filter(d=>!s.contracts.some(c=>c.id===d.contract)&&d.currency==='UZS').reduce((a,d)=>a+d.amount,0),max=Math.max(...totals,other,1);return`<section class="hero"><img src="assets/brain.webp" alt="Скульптура цифрового мозга из кобальтового стекла"><div class="hero-copy"><span class="eyebrow">✦ TEJAM INTELLIGENCE</span><h2>Замечает детали.<br>Сохраняет средства.</h2><p>Проверяйте счета, находите расхождения и принимайте решения с доказательствами.</p>${btn('Проверить расходы ↗','scan','mint')}</div></section><section class="kpis">${[['Расходы в UZS',compact(s.invoices.filter(d=>d.currency==='UZS').reduce((a,d)=>a+d.amount,0)),'Другие валюты учитываются отдельно','↗'],['Потенциальная переплата',compact(exposure(fs)),'Оценка, не фактическая экономия','◇'],['Ожидают решения',open.length,'Сигналы по активным правилам','◷'],['Проверено документов',s.invoices.length,'Договоры · счета · реквизиты','✓']].map(k=>`<article class="kpi"><div class="label">${k[0]}<span>${k[3]}</span></div><strong>${k[1]}</strong><small>${k[2]}</small></article>`).join('')}</section><div class="grid"><section class="card chartspace"><div class="cardhead"><h2>Структура расходов</h2><span class="tag">UZS · все счета</span></div><div class="bars">${[...totals,other].map((t,i)=>`<div class="baritem"><span>${compact(t)}</span><div class="bar" style="height:${t/max*140}px"></div><small>${['Связь','ПО','Энергия','Сервис','Аренда','Прочее'][i]}</small></div>`).join('')}</div></section><section class="card"><div class="cardhead"><h2>Карта сигналов</h2><span class="tag">Живой расчёт</span></div><div class="risk"><div class="donut" style="background:conic-gradient(#245afa 0 ${fs.length?open.length/fs.length*100:0}%,#e8eefb 0)"><div><b>${fs.length}</b><small>найдено сигналов</small></div></div><div class="legend"><div><i></i> ${open.length} ожидают</div><div><i style="background:#b9ccff"></i> ${fs.filter(f=>f.status==='confirmed').length} подтверждены</div><div><i style="background:#e8eefb"></i> ${fs.filter(f=>f.status==='dismissed').length} сняты</div></div></div></section></div><div class="grid"><section class="card"><div class="cardhead"><h2>Требуют внимания</h2><button class="textbtn" data-page="checks">Все сигналы ↗</button></div>${table(open.slice(0,5))}</section><div><section class="card"><div class="cardhead"><h2>Контроль на каждом этапе</h2><span class="tag">14 правил</span></div>${[['01','Документ','Проверка суммы, ставки и повторных счетов'],['02','Договор','Тарифы, объёмы и допсоглашения'],['03','Решение','Доказательства и след действий']].map(x=>`<div class="summary"><span class="square">${x[0]}</span><div><b>${x[1]}</b><p>${x[2]}</p></div></div>`).join('')}</section><section class="bankcard"><img src="assets/bank.webp" alt="Концептуальная визуализация офиса компании"><div><span class="eyebrow">BUILT FOR FINANCE TEAMS</span><h2>Один стандарт.<br>Для всех точек.</h2><p>Сопоставляйте расходы и находите услуги, которые больше не нужны.</p><button class="btn" data-page="branches">Открыть точкаы ↗</button></div></section></div></div>`}if(page==='checks')return`<div class="filters"><input id="search" type="search" aria-label="Поиск сигналов" placeholder="Поиск по счёту, поставщику, типу ошибки" value="${esc(query)}"><select id="filter" aria-label="Статус">${[['all','Все статусы'],['open','Ожидают решения'],['confirmed','Подтверждены'],['dismissed','Сняты'],['requested','Запрошены данные']].map(x=>`<option value="${x[0]}" ${filter===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><section class="card" id="results">${filtered(fs)}</section>`;
if(page==='documents')return`<div class="notice">Счёт — документ поставщика за интернет, электричество, аренду или другие услуги бизнесу. Tejam сопоставляет его с условиями договора. Все поставщики в демо вымышлены.</div><section class="card"><div class="cardhead"><h2>Реестр документов</h2>${btn('＋ Добавить вручную','newinvoice')}</div><div class="tablewrap"><table><thead><tr><th>НОМЕР</th><th>ПОСТАВЩИК / УСЛУГА</th><th>ПЕРИОД</th><th>СУММА</th><th>СИГНАЛЫ</th><th></th></tr></thead><tbody>${s.invoices.map(d=>`<tr><td>${esc(d.id)}</td><td><strong>${esc(vn(d.vendor))}</strong><small>${esc(d.service)}</small></td><td>${d.period}</td><td>${money(d.amount)} ${d.currency}</td><td>${fs.filter(f=>f.invoice===d.id).length}</td><td><button class="textbtn" data-edit="${esc(d.id)}">Открыть ↗</button></td></tr>`).join('')}</tbody></table></div></section>`;
if(page==='contracts')return`<div class="notice">Допсоглашения меняют цену и объём с указанной даты. После изменения результаты проверок пересчитываются; прежние решения сбрасываются.</div><div class="vendorgrid">${s.contracts.map(c=>`<section class="card"><div class="cardhead"><span class="tag">${c.id}</span><span class="tag">${c.currency}</span></div><h2>${esc(c.service)}</h2><p>${esc(vn(c.vendor))}</p><div class="evidence">${money(c.unit)} ${c.currency} / единица<br>Объём: ${c.qty}<br>До ${c.end}<br>Допсоглашений: ${c.amendments.length}</div><button class="btn" data-contract="${c.id}">Допсоглашение ＋</button></section>`).join('')}</div>`;
if(page==='vendors')return`<div class="notice">Поставщик оказывает бизнесу услугу и выставляет счёт. Ошибка может появиться в его счёте или при вводе данных сотрудником. Сигнал не означает мошенничество.</div><div class="vendorgrid">${s.vendors.map(v=>`<section class="card"><div class="vendorlogo">${v.name.split(' ').map(x=>x[0]).join('')}</div><h2>${v.name}</h2><p>Подтверждённый счёт<br>${v.bank}</p><div class="evidence">${s.invoices.filter(d=>d.vendor===v.id).length} документов<br>${fs.filter(f=>s.invoices.find(d=>d.id===f.invoice)?.vendor===v.id).length} сигналов для проверки</div></section>`).join('')}</div>`;
if(page==='branches')return`<div class="vendorgrid">${s.branches.map(b=>`<section class="card"><img src="assets/bank.webp" style="width:100%;height:120px;object-fit:cover;border-radius:10px;margin-bottom:18px" alt="Концептуальная визуализация точки"><div class="cardhead"><h2>${b.name}</h2><span class="tag ${b.active?'low':'high'}">${b.active?'Активен':'Закрыт'}</span></div><p>${compact(s.invoices.filter(d=>d.branch===b.id&&d.currency==='UZS').reduce((a,d)=>a+d.amount,0))} UZS</p><p>${s.invoices.filter(d=>d.branch===b.id).length} счетов</p><button class="textbtn" data-branch="${b.id}">${b.active?'Отметить закрытым':'Восстановить точка'} ↗</button></section>`).join('')}</div>`;
if(page==='audit')return`<section class="card"><div class="cardhead"><h2>История действий</h2>${btn('↓ Скачать журнал','auditexport')}</div><div class="tablewrap"><table><thead><tr><th>ВРЕМЯ</th><th>ДЕЙСТВИЕ</th><th>ОБЪЕКТ</th><th>КОММЕНТАРИЙ</th></tr></thead><tbody>${s.log.map(l=>`<tr><td>${esc(l.date)}</td><td>${esc(l.action)}</td><td>${esc(l.target)}</td><td style="white-space:normal">${esc(l.note)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Решения появятся здесь после разбора сигналов</td></tr>'}</tbody></table></div></section>`;
if(page==='rules')return`<section class="card"><div class="formgrid" style="margin-bottom:22px"><label>Внутренний лимит, UZS<input id="limit" type="number" value="${s.limit}" min="1"></label><label>Дата оценки окончания договоров<input id="asof" type="date" value="${s.asOf}"></label></div><div class="checks">${rules.map((r,i)=>`<label class="checkrow"><input type="checkbox" data-rule="${r[0]}" ${s.enabled.includes(r[0])?'checked':''}><div><b>${String(i+1).padStart(2,'0')} · ${r[1]}</b><br><small>Объяснимое правило · ${fs.filter(f=>f.rule===r[0]).length} сигналов</small></div></label>`).join('')}</div></section>`;
if(page==='upload')return`<div class="grid"><section class="card"><h2>От документа к проверке</h2><p>Загрузите CSV, текстовый PDF или TXT.</p><button id="dropzone" class="dropzone" style="margin:22px 0"><span style="font-size:36px;color:#245afa">⇧</span><b>Выберите документ</b><p>До 10 МБ · PDF до 30 страниц<br>Сканированные изображения требуют OCR — он не подключён</p></button><input id="file" type="file" accept=".pdf,.txt,.csv" hidden><div class="actions">${btn('Пример TXT','sample')}${btn('Шаблон CSV','template')}${btn('Ввести вручную','newinvoice')}</div><div id="importstatus" class="notice" style="margin-top:20px">Файлы обрабатываются в вашем браузере. PDF/TXT заполняют черновик — подтвердите распознанные поля.</div></section><section class="card"><h2>Что проверит Tejam</h2>${[['01','Суммы и реквизиты','Арифметика, повторы, валюта и получатель'],['02','Условия договора','Цена, количество, период, подтверждающий акт'],['03','Контекст расходов','Филиал, внутренний лимит и срок продления']].map(x=>`<div class="summary"><span class="square">${x[0]}</span><div><b>${x[1]}</b><p>${x[2]}</p></div></div>`).join('')}<div class="notice">Демо использует программные правила. LLM, учётные API и настоящий OCR не подключены.</div></section></div>`;
if(page==='demo')return`<section class="hero" style="margin-bottom:22px"><img src="assets/brain.webp" alt="Цифровой мозг"><div class="hero-copy"><span class="eyebrow">THE 90-SECOND DEMO</span><h2>Не просто сигнал.<br>Обоснованное решение.</h2><p>Покажите менторам, как система меняет вывод, когда меняются доказательства.</p></div></section><div class="steps">${[['01','Находим переплату','50 подключений по 240 000 вместо договорных 200 000. Потенциальная разница — 2 млн UZS.','demo1','Открыть расхождение'],['02','Учитываем изменение','Добавляем допсоглашение с новой ценой 240 000 с 1 ноября. Предупреждение о цене снимается.','demo2','Добавить допсоглашение'],['03','Принимаем решение','Другой счёт повторяет уже выставленный. Сотрудник изучает основания и фиксирует решение.','demo3','Разобрать повтор']].map(x=>`<section class="card step"><div class="num">${x[0]}</div><h2>${x[1]}</h2><p>${x[2]}</p>${btn(x[4],x[3],'primary')}</section>`).join('')}</div><div class="notice" style="margin-top:20px">Шаги изменяют демонстрационные данные. Первый шаг восстанавливает исходную цену C-101. Реальных платежей нет.</div>${btn('Сбросить демоданные','reset')}`;
return`<section class="card about"><h2>Tejam — контроль операционных расходов</h2><p>Проблема: ошибки в счетах, ручном вводе и согласовании расходов обнаруживаются слишком поздно. Решение: сопоставить документ, условия договора и сведения о поставщике, показать расхождение и оставить окончательное решение человеку.</p><h3>Что работает в этой версии</h3><ul><li>14 правил контроля; изменение исходных данных действительно меняет результат.</li><li>Импорт CSV, извлечение текста PDF/TXT, редактирование документов и допсоглашения.</li><li>Решения с комментариями, локальный журнал, экспорт CSV и адаптивный интерфейс.</li></ul><h3>Что нужно для внедрения</h3><p>Серверная авторизация и роли, защищённое хранение, интеграции с учётными системами, OCR и языковая модель для извлечения полей и поиска условий договора. Затем тестирование на размеченных документах бизнеса с измерением точности и ложных сигналов.</p><h3>Честные ограничения</h3><p>Это прототип с правилами, без подключённой модели ИИ. Данные хранятся только в localStorage текущего браузера. Журнал можно изменить или очистить; это не защищённый аудит. Анализ периода выполняется по месяцу, допсоглашение выбирается по дате счёта. Суммы разных валют не складываются. Потенциальная переплата учитывает максимум на документ, а не сумму пересекающихся сигналов. Она не равна доказанному убытку или фактической экономии.</p><h3>Исследование и позиционирование</h3><p>Аналоги существуют, в том числе в Узбекистане. Отличие нашего демонстрационного сценария — связка «счёт → договор → допсоглашение → доказательство → решение», а не утверждение об уникальности технологии.</p><ul><li><a href="https://centa.uz/ru/features/transactions" target="_blank" rel="noopener">Centa: операции и сверка</a></li><li><a href="https://support.ramp.com/ap-agents-available-in-ramp-bill-pay/" target="_blank" rel="noopener">Ramp: автоматизация проверки счетов</a></li></ul><p>Демо-проверки и поставщики вымышлены. Точки показаны карточками с иллюстративными фотографиями без фотографий реальных объектов. Помощник отвечает по шаблонам. Возвраты фиксируются вручную; деньги и сообщения не отправляются. Проект не является продуктом или официальным партнёром SQB либо AI Alliance.</p></section>`}
function filtered(fs){return table(fs.filter(f=>(filter==='all'||f.status===filter)&&[f.title,f.invoice,vn(s.invoices.find(d=>d.id===f.invoice).vendor)].join(' ').toLowerCase().includes(query.toLowerCase())))}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();window.scrollTo(0,0)});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));bindCases();document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>invoiceForm(s.invoices.find(d=>d.id===b.dataset.edit)));document.querySelectorAll('[data-contract]').forEach(b=>b.onclick=()=>amendForm(b.dataset.contract));document.querySelectorAll('[data-branch]').forEach(b=>b.onclick=()=>{let branch=s.branches.find(x=>x.id===b.dataset.branch);branch.active=!branch.active;s.decisions={};log('Изменён статус точки',branch.name);render()});document.querySelectorAll('[data-rule]').forEach(b=>b.onchange=()=>{s.enabled=b.checked?[...s.enabled,b.dataset.rule]:s.enabled.filter(r=>r!==b.dataset.rule);log('Изменено правило',b.dataset.rule);render()});if($('#search'))$('#search').oninput=e=>{query=e.target.value;$('#results').innerHTML=filtered(check(s));bindCases()};if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;render()};if($('#limit'))$('#limit').onchange=e=>{if(Number(e.target.value)>0){s.limit=Number(e.target.value);log('Изменён лимит',s.limit);render()}};if($('#asof'))$('#asof').onchange=e=>{if(e.target.value){s.asOf=e.target.value;persist();render()}};if($('#file')){$('#dropzone').onclick=()=>$('#file').click();$('#file').onchange=e=>importFile(e.target.files[0])}}
function bindCases(){document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>caseModal(b.dataset.case))}function modal(html){$('#modal').classList.remove('wide-modal');$('#modal').innerHTML=`<div class="modalhead"><h2>Tejam · Детали проверки</h2><button id="close" aria-label="Закрыть">×</button></div>${html}`;$('#close').onclick=()=>$('#modal').close();if(!$('#modal').open)$('#modal').showModal()}
function caseModal(id){let f=check(s).find(f=>f.id===id);if(!f)return toast('Сигнал больше не актуален');let d=s.invoices.find(d=>d.id===f.invoice);modal(`${tag(f)}<h2 style="margin-top:16px">${f.title}</h2><p>${esc(vn(d.vendor))} · ${d.id} · ${d.contract||'Без договора'}</p><div class="evidence"><b>Основание проверки</b><br>${esc(f.detail)}${f.rule==='price'?quoteEvidence(d):''}<br><br>Источник: поля счёта ${d.id}, реестр поставщиков и договор ${d.contract||'не найден'}.${f.exposure?`<br><b>Потенциальная разница: ${money(f.exposure)} ${f.currency}</b>`:''}</div><p class="sub">Сигнал требует проверки человеком. Решение не отправляет платёж и не связывается с поставщиком.</p><textarea id="note" placeholder="Комментарий обязателен: что проверено и почему принято решение" aria-label="Комментарий к решению">${esc(s.decisions[id]?.note||'')}</textarea><div class="actions">${btn('Запросить данные','requested')}${btn('Снять сигнал','dismissed')}${btn('Подтвердить','confirmed','primary')}</div>`);$('#modal').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{let note=$('#note').value.trim();if(!note)return toast('Добавьте комментарий к решению');s.decisions[id]={status:b.dataset.action,note};log({requested:'Запрошены данные',dismissed:'Сигнал снят',confirmed:'Сигнал подтверждён'}[b.dataset.action],id,note);$('#modal').close();render();toast('Решение сохранено в журнале')})}
function download(name,text,type='text/csv;charset=utf-8'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function toCSV(rows){return rows.map(r=>r.map(x=>'"'+(/^[=+@-]/.test(String(x))?"'":'')+String(x??'').replaceAll('"','""')+'"').join(';')).join('\n')}
function action(a){if(a==='menu')return $('aside').classList.toggle('open');if(a==='upload'){page='upload';render()}if(a==='scan'){page='checks';render();toast('Проверка завершена: '+check(s).length+' сигналов')}if(a==='newinvoice')invoiceForm();if(a==='export')download('tejam-report.csv',toCSV([['Счёт','Правило','Обоснование','Разница','Валюта','Статус'],...check(s).map(f=>[f.invoice,f.title,f.detail,f.exposure,f.currency,f.status])]));if(a==='auditexport')download('tejam-audit.csv',toCSV([['Время','Действие','Объект','Комментарий'],...s.log.map(l=>[l.date,l.action,l.target,l.note])]));if(a==='sample')download('sample-invoice.txt','Номер: TEST-101\nДата: 2026-11-17\nПериод: 2026-11\nДоговор: C-101\nУслуга: Интернет\nКоличество: 50\nЦена: 240000\nСтавка: 0\nИтого: 12000000\nВалюта: UZS\nСчёт получателя: 202080001','text/plain;charset=utf-8');if(a==='template')download('tejam-template.csv',toCSV([['id','vendor','branch','date','period','contract','service','qty','unit','tax','amount','currency','bank','accepted'],['TEST-CSV-101','v1','b1','2026-11-17','2026-11','C-101','Интернет',50,240000,0,12000000,'UZS','202080001','true']]));if(a==='demo1'){let c=s.contracts.find(c=>c.id==='C-101');c.amendments=[];c.unit=200000;s.decisions={};log('Демо: исходная цена',c.id);render();caseModal('price:INV-001')}if(a==='demo2'){let c=s.contracts.find(c=>c.id==='C-101');c.amendments=[{date:'2026-11-01',unit:240000,qty:50}];s.decisions={};log('Добавлено допсоглашение',c.id,'240 000 UZS с 2026-11-01');render();toast('Цена подтверждена договором: сигнал INV-001 снят. Лимит проверяется отдельно.')}if(a==='demo3')caseModal('duplicate:INV-003');if(a==='reset'){modal('<p>Удалить локальные изменения, решения и импортированные документы? Будут восстановлены исходные демоданные.</p><div class="actions"><button id="resetyes" class="btn primary">Восстановить демоданные</button></div>');$('#resetyes').onclick=()=>{s=seed();persist();$('#modal').close();render();toast('Демоданные восстановлены')}}}
function invoiceForm(d=null,source=''){let editing=d&&s.invoices.some(x=>x.id===d.id),v=d||{id:'NEW-'+Date.now().toString().slice(-6),vendor:'v1',branch:'b1',contract:'C-101',date:s.asOf,period:s.asOf.slice(0,7),service:'Интернет',qty:50,unit:200000,tax:0,amount:10000000,currency:'UZS',bank:'202080001',accepted:true};const field=(k,label,type='text')=>`<label>${label}<input name="${k}" type="${type}" value="${esc(v[k])}" ${k==='id'&&editing?'readonly':''} required ${['qty','unit','amount','tax'].includes(k)?'min="0" step="any"':''}></label>`;modal(`<form id="invoiceform"><div class="formgrid">${field('id','Номер счёта')}${field('date','Дата','date')}<label>Поставщик<select name="vendor">${s.vendors.map(x=>`<option value="${x.id}" ${v.vendor===x.id?'selected':''}>${x.name}</option>`).join('')}</select></label><label>Филиал<select name="branch">${s.branches.map(x=>`<option value="${x.id}" ${v.branch===x.id?'selected':''}>${x.name}</option>`).join('')}</select></label><label>Договор<select name="contract"><option value="">Без договора</option>${s.contracts.map(x=>`<option value="${x.id}" ${v.contract===x.id?'selected':''}>${x.id} · ${x.service}</option>`).join('')}</select></label>${field('period','Период услуги','month')}${field('service','Услуга')}${field('bank','Счёт получателя')}${field('qty','Количество','number')}${field('unit','Цена за единицу','number')}${field('tax','Ставка, %','number')}${field('amount','Итоговая сумма','number')}<label>Валюта<select name="currency">${['UZS','USD','EUR'].map(x=>`<option ${v.currency===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Счёт оплачен<select name="paid"><option value="false" ${!v.paid?'selected':''}>Нет</option><option value="true" ${v.paid?'selected':''}>Да · ручная отметка</option></select></label><label>Акт получен<select name="accepted"><option value="true" ${v.accepted?'selected':''}>Да</option><option value="false" ${!v.accepted?'selected':''}>Нет</option></select></label></div>${source?`<details style="margin-top:18px"><summary>Исходный текст документа</summary><pre class="docpreview">${esc(source)}</pre></details>`:''}<div class="actions"><button class="btn primary" type="submit">Сохранить и проверить</button></div></form>`);$('#invoiceform').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));for(let k of ['qty','unit','tax','amount'])x[k]=Number(x[k]);x.accepted=x.accepted==='true';x.paid=x.paid==='true';let error=validateInvoice(x,editing);if(error)return toast(error);if(editing)s.invoices=s.invoices.map(old=>old.id===x.id?{...old,...x}:old);else s.invoices.push(x);s.decisions={};log(editing?'Изменён счёт':'Добавлен счёт',x.id);$('#modal').close();page='checks';query=x.id;filter='all';render()}}
function validateInvoice(x,editing=false){if(!x.id||(!editing&&s.invoices.some(d=>d.id===x.id)))return'Номер счёта должен быть уникальным';if(!s.vendors.some(v=>v.id===x.vendor)||!s.branches.some(b=>b.id===x.branch))return'Неизвестный поставщик или точка';if(!/^\d{4}-\d{2}-\d{2}$/.test(x.date)||!/^\d{4}-\d{2}$/.test(x.period)||isNaN(Date.parse(x.date)))return'Проверьте дату и период';if(!['UZS','USD','EUR'].includes(x.currency))return'Валюта должна быть UZS, USD или EUR';if(['qty','unit','amount'].some(k=>!Number.isFinite(x[k])||x[k]<=0)||!Number.isFinite(x.tax)||x.tax<0)return'Суммы и количество должны быть положительными';let c=s.contracts.find(c=>c.id===x.contract);if(x.contract&&!c)return'Договор не найден';if(c&&c.vendor!==x.vendor)return'Поставщик не совпадает с договором';return''}
function amendForm(id){let c=s.contracts.find(c=>c.id===id);modal(`<h2>${id} · Допсоглашение</h2><p>Новые условия применяются к счетам с указанной даты. Прежние решения будут сброшены.</p><form id="amend"><div class="formgrid" style="margin-top:20px"><label>Действует с<input name="date" type="date" required value="${s.asOf}"></label><label>Новая цена<input name="unit" type="number" min="0.01" step="any" value="${c.unit}" required></label><label>Договорной объём<input name="qty" type="number" min="0.01" step="any" value="${c.qty}" required></label></div><div class="actions"><button class="btn primary">Применить и пересчитать</button></div></form>`);$('#amend').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.unit=+x.unit;x.qty=+x.qty;if(c.amendments.some(a=>a.date===x.date))return toast('На эту дату уже есть допсоглашение');c.amendments.push(x);s.decisions={};log('Добавлено допсоглашение',id,`${x.date}: ${x.unit} ${c.currency}, объём ${x.qty}`);$('#modal').close();render();toast('Условия обновлены, проверки пересчитаны')}}
async function importFile(file){if(!file)return;if(file.size>10*1024*1024)return toast('Максимальный размер 10 МБ');try{$('#importstatus').textContent='Читаем документ…';let ext=file.name.split('.').pop().toLowerCase(),text='';if(ext==='pdf'){pdfjsLib.GlobalWorkerOptions.workerSrc='assets/pdf.worker.min.js';let doc=await pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;if(doc.numPages>30)throw Error('PDF должен содержать не более 30 страниц');for(let i=1;i<=doc.numPages;i++){let p=await doc.getPage(i),tc=await p.getTextContent(),y=null;for(let item of tc.items){if(y!==null&&Math.abs(item.transform[5]-y)>2)text+='\n';text+=item.str+' ';y=item.transform[5]}text+='\n'}if(text.trim().length<20)throw Error('В PDF нет текстового слоя. Для скана требуется OCR.')}else if(['txt','csv'].includes(ext))text=await file.text();else throw Error('Поддерживаются PDF, TXT и CSV');if(ext==='csv'){let rows=csv(text.replace(/^\ufeff/,''));if(!rows.length||rows.length>1000)throw Error('CSV должен содержать от 1 до 1000 строк');let seen=new Set;for(let x of rows){for(let k of ['qty','unit','amount'])x[k]=Number(x[k]);x.tax=Number(x.tax||0);x.accepted=x.accepted==='true';x.paid=x.paid==='true';x.contract=x.contract||'';let err=validateInvoice(x);if(err)throw Error(`${x.id||'Строка'}: ${err}`);if(seen.has(x.id))throw Error('Повтор номера в CSV');seen.add(x.id)}s.invoices.push(...rows);s.decisions={};log('Импорт CSV',file.name,`${rows.length} документов`);page='documents';render();toast('CSV импортирован: '+rows.length+' документов');return}let get=label=>(text.match(new RegExp('(?:^|\\n)\\s*'+label+'\\s*:\\s*([^\\n]+)','i'))||[])[1]?.trim();let num=(label,def)=>Number((get(label)||String(def)).replace(/\s/g,'').replace(',','.'));let cid=get('Договор')||'',c=s.contracts.find(c=>c.id===cid),vendor=c?.vendor||'v1';invoiceForm({id:get('Номер')||'IMPORT-'+Date.now(),date:get('Дата')||s.asOf,period:get('Период')||s.asOf.slice(0,7),contract:cid,vendor,branch:'b1',service:get('Услуга')||c?.service||'Услуга',qty:num('Количество',1),unit:num('Цена',0),tax:num('Ставка',0),amount:num('Итого',0),currency:get('Валюта')||'UZS',bank:get('Счёт получателя')||'',accepted:false},text);$('#importstatus').textContent='Текст извлечён. Проверьте поля и выберите точка перед сохранением.'}catch(e){$('#importstatus').textContent=e.message;toast(e.message)}}
let theme=localStorage.getItem('tejam-theme')||'dark',chatOpen=false,chatMessages=[],contractTarget='';
const sim='<span class="sim">симуляция</span>',palette=['#ff9565','#d4a17b','#a57862','#785c50','#584940'];
function icon(id){const p={telegram:'m3 11 18-7-4 17-6-5-3 3v-5l10-8-12 6z',overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',checks:'m12 3 9 9-9 9-9-9z M8 12l3 3 5-6',documents:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',contracts:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',recovery:'M5 9a8 8 0 1 1-1 7 M5 3v6h6',vendors:'M8 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-4a6 6 0 0 1 12 0v4 M17 5a3 3 0 0 1 0 6 M17 14a5 5 0 0 1 5 5v2',branches:'M3 21h18 M5 21V8l7-5 7 5v13 M9 10v3 M15 10v3 M9 16v3 M15 16v3',audit:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l4 2',rules:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',theme:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',chat:'M20 11a8 8 0 0 1-8 8H7l-4 3v-7a8 8 0 1 1 17-4Z M7 10h10 M7 14h6'};return`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${p[id]||p.overview}"/></svg>`}
function content(fs,open){if(page==='overview')return dashboard(fs,open);if(page==='recovery')return recoveryPage(fs);if(page==='contracts')return contractsPage();if(page==='branches')return branchesPage(fs);return legacyContent(fs,open)}
function delta(a,b){return b===0?'нет базы':`${a>=b?'+':''}${((a-b)/b*100).toLocaleString('ru-RU',{maximumFractionDigits:1})}%`}
function sumUZS(rows,key='amount'){return rows.filter(r=>r.currency==='UZS').reduce((a,r)=>a+r[key],0)}
function dashboard(fs,open){let month=s.asOf.slice(0,7),date=new Date(month+'-01T12:00:00Z');date.setUTCMonth(date.getUTCMonth()-1);let prev=date.toISOString().slice(0,7),now=monthStats(s,fs,month),before=monthStats(s,fs,prev),rs=recoveries(s,fs),cats=s.vendors.map((v,i)=>({name:['Связь','ПО и лицензии','Энергия','Обслуживание','Аренда'][i],amount:sumUZS(s.invoices.filter(d=>d.vendor===v.id))})),total=cats.reduce((a,c)=>a+c.amount,0),angle=0;let slices=cats.map((c,i)=>{let start=angle;angle+=total?c.amount/total*100:0;return`${palette[i]} ${start}% ${angle}%`}).join(',');return`<div class="dashwelcome"><span class="eyebrow">FINANCIAL CONTROL, REIMAGINED</span><div class="pillnav"><button class="selected" data-page="overview">Обзор</button><button data-page="checks">Аналитика</button><button data-page="recovery">Возврат средств</button></div></div><section class="kpis">${[['Расходы за месяц',compact(now[0]),'UZS · '+month],['Потенциальная переплата',compact(now[1]),'Оценка · '+month],['Ожидают решения',now[2],'Сигналы · '+month],['Проверено документов',now[3],'Счета · '+month]].map((k,i)=>`<article class="kpi ${i===0?'gradient':''}"><div class="label">${k[0]}<span class="metricicon">${icon(['recovery','checks','audit','documents'][i])}</span></div><strong>${k[1]}</strong><div class="kpibottom"><small>${k[2]}</small><span class="percent" title="Изменение к ${prev} по загруженным данным">${delta(now[i],before[i])}</span></div></article>`).join('')}</section><p class="metricnote">Изменения к ${prev} рассчитаны по загруженным счетам. Месяцы могут быть неполными; это не реальная статистика бизнеса.</p><div class="analyticsgrid"><section class="card areacard"><div class="cardhead"><div><span class="eyebrow">CASHFLOW INTELLIGENCE</span><h2>Пульс расходов</h2></div><span class="tag">${month} · UZS</span></div>${areaChart(month)}<div class="chartcaption"><span>● Сумма счетов по дням</span><span>Выберите точку на графике</span></div></section><section class="card summarycard"><div class="cardhead"><span class="eyebrow">RECOVERY CENTER</span><span class="roundicon">${icon('recovery')}</span></div><p>Найдено к возврату</p><strong class="bigmoney">${compact(sumUZS(rs))}<small> UZS</small></strong><p class="sub">По оплаченным счетам · все стадии</p><div class="returnline"><span>Отмечено возвращённым</span><b>${compact(sumUZS(rs.filter(r=>r.status==='returned')))} UZS</b></div><button class="btn primary" data-page="recovery">Разобрать случаи ↗</button><small>Ручные отметки · демоданные</small></section></div><div class="analyticsgrid"><section class="card"><div class="cardhead"><div><span class="eyebrow">EXPENSE SPLIT</span><h2>На что уходят средства</h2></div><span class="tag">Все периоды · UZS</span></div><div class="splitcontent"><div class="donut" style="background:conic-gradient(${slices})"><div><small>Всего</small><b>${compact(total)}</b><small>UZS</small></div></div><div class="splitlegend">${cats.map((c,i)=>`<div><span><i style="background:${palette[i]}"></i>${c.name}</span><b>${total?(c.amount/total*100).toFixed(1):0}%</b><small>${compact(c.amount)}</small></div>`).join('')}</div></div></section><section class="card"><div class="cardhead"><div><span class="eyebrow">BRANCH COMPARISON</span><h2>Расходы по точким</h2></div><span class="tag">UZS</span></div>${branchBars()}<p class="sub">Выделен точка с наибольшей суммой счетов.</p></section></div><section class="card"><div class="cardhead"><div><span class="eyebrow">TRANSACTION REVIEW</span><h2>Требуют внимания</h2></div><button class="textbtn" data-page="checks">Все сигналы (${open.length}) ↗</button></div>${table([...open].sort((a,b)=>({high:0,medium:1,low:2}[a.severity]-{high:0,medium:1,low:2}[b.severity])).slice(0,6))}</section><div class="dashboardbottom"><div><b>Сигнал — повод проверить, а не обвинение.</b><p>Сверяйте документы и фиксируйте решение. Сигнал не означает мошенничество.</p></div><button class="btn" data-page="demo">Запустить демо ↗</button></div>`}
function areaChart(month){let days=new Date(+month.slice(0,4),+month.slice(5),0).getDate(),values=Array.from({length:days},(_,i)=>sumUZS(s.invoices.filter(d=>d.date===month+'-'+String(i+1).padStart(2,'0')))),max=Math.max(...values,1),pts=values.map((v,i)=>[25+i*650/(days-1),190-v/max*140]),line=pts.map(p=>p.join(',')).join(' '),p=pts[14];return`<div class="area-wrap"><div class="charttip" id="charttip"><small>15 · ${month}</small><b>${money(values[14])} UZS</b></div><svg class="area" viewBox="0 0 700 225" role="group" aria-label="Дневные расходы по счетам"><defs><linearGradient id="areaFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#ff9d73" stop-opacity=".4"/><stop offset="100%" stop-color="#ff9d73" stop-opacity="0"/></linearGradient></defs>${[50,95,140,190].map(y=>`<line x1="25" x2="675" y1="${y}" y2="${y}" stroke="currentColor" opacity=".08"/>`).join('')}<polygon points="25,190 ${line} 675,190" fill="url(#areaFill)"/><polyline points="${line}" fill="none" stroke="#ff9d73" stroke-width="2.5" stroke-linejoin="round"/><line id="chartline" x1="${p[0]}" x2="${p[0]}" y1="30" y2="195" stroke="#cab4a9" stroke-dasharray="4 5" opacity=".7"/><circle id="chartdot" cx="${p[0]}" cy="${p[1]}" r="5" fill="#fff0dc" stroke="#ff8651" stroke-width="4"/>${pts.map((p,i)=>`<circle class="chartpoint" data-chart="${i}" data-x="${p[0]}" data-y="${p[1]}" data-value="${values[i]}" data-month="${month}" cx="${p[0]}" cy="${p[1]}" r="11" fill="transparent" tabindex="0" role="button" aria-label="${i+1} ${month}: ${money(values[i])} UZS"/>`).join('')}${[0,7,14,21,days-1].map(i=>`<text x="${pts[i][0]}" y="218" fill="currentColor" opacity=".5" font-size="10" text-anchor="middle">${i+1}</text>`).join('')}</svg></div>`}
function branchBars(){let vals=s.branches.map(b=>sumUZS(s.invoices.filter(d=>d.branch===b.id))),max=Math.max(...vals,1);return`<div class="bars">${vals.map((v,i)=>`<div class="baritem"><span>${compact(v)}</span><div class="bar ${v===max?'highlight':''}" style="height:${v/max*135}px"></div><small>${s.branches[i].name}</small></div>`).join('')}</div><div style="height:25px"></div>`}
function branchesPage(fs){return`<div class="notice">Метрики рассчитаны по демосчетам. Фотографии — реальные здания из Pexels, иллюстрации, а не адреса указанных точек.</div><div class="branchgrid">${s.branches.map((b,i)=>{let ds=s.invoices.filter(d=>d.branch===b.id),f=fs.filter(f=>ds.some(d=>d.id===f.invoice));return`<section class="card branch ${!b.active?'closed':''}"><div class="branchvisual"><span class="branchcode">${['TAS / 01','CHL / 02','SAM / 03','YUN / 04'][i]}</span><img src="assets/branch-${i+1}.webp" alt="Фотография офисного здания — иллюстрация демоточки" loading="lazy"><span class="photocredit">Фото · Pexels</span><span class="tag">${b.active?'Действующий':'Закрытый точка'}</span></div><div class="cardhead"><h2>${b.name}</h2><span class="roundicon">${icon('branches')}</span></div><p>${i===2?'Самарканд':'Ташкент'} · демонстрационный объект</p><strong class="branchamount">${compact(sumUZS(ds))}<small> UZS</small></strong><div class="branchmetrics"><span>${ds.length} счетов</span><span>${f.length} сигналов</span></div><button class="btn" data-branch="${b.id}">${b.active?'Отметить закрытым':'Восстановить точка'}</button></section>`}).join('')}</div>`}
function recoveryPage(fs){let rs=recoveries(s,fs);return`<section class="recoveryhero card"><div><span class="eyebrow">MODULE 05 / RECOVERY</span><h2>Каждая переплата<br>заслуживает возврата.</h2><p>Сверьте основание, подготовьте претензию,<br>зафиксируйте результат.</p></div><div><p>Найдено к возврату · все стадии</p><strong>${compact(sumUZS(rs))}<small> UZS</small></strong><span>${rs.length} случаев · оценка по оплаченным счетам</span></div></section><div class="notice">На обзоре — потенциальные переплаты по всем счетам выбранного месяца, в том числе неоплаченным. Здесь — денежные сигналы по оплаченным счетам всех периодов. На один счёт берётся максимум, без двойного сложения. Платёжные операции не подключены: оплата отмечается вручную. Сигнал не означает мошенничество.</div><div class="funnel">${[['found','Найдено','01'],['sent','Претензия отправлена','02'],['returned','Возвращено','03']].map(([status,title,num])=>{let rows=rs.filter(r=>r.status===status);return`<section class="card ${status==='returned'?'successcard':''}"><span class="eyebrow">${num} / ${title}</span><strong>${compact(sumUZS(rows))}<small> UZS</small></strong><p>${rows.length} случаев</p></section>`}).join('')}</div><section class="card"><div class="cardhead"><h2>Случаи для сверки</h2>${sim}</div><div class="tablewrap"><table><thead><tr><th>СЧЁТ / ПОСТАВЩИК</th><th>ОСНОВАНИЕ</th><th>К ВОЗВРАТУ</th><th>РЕШЕНИЕ</th><th>СТАДИЯ</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td><button class="textbtn" data-edit="${r.id}">${r.id}</button><small>${vn(r.d.vendor)}</small></td><td><button class="textbtn" data-case="${r.primary.id}">${r.primary.title}</button>${r.stale?'<small>Условия изменились: повторите сверку</small>':''}</td><td><b>${money(r.amount)} ${r.currency}</b></td><td><span class="tag ${r.confirmed?'confirmed':''}">${r.confirmed?'Подтверждено':'Нужна проверка'}</span></td><td><select class="${r.status==='returned'?'returned':''}" data-recovery="${r.id}" aria-label="Статус возврата ${r.id}">${[['found','Найдено'],['sent','Претензия отправлена'],['returned','Возвращено']].map(([v,t])=>`<option value="${v}" ${v===r.status?'selected':''}>${t}</option>`).join('')}</select></td><td><button class="btn" data-claim="${r.id}">Создать претензию</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Нет активных денежных сигналов по оплаченным счетам.</td></tr>'}</tbody></table></div></section><p class="metricnote">Претензии не отправляются из приложения. Стадии «отправлена» и «возвращено» отмечает сотрудник после проверки. Снятые основания исключаются из текущего расчёта; история остаётся в журнале.</p>`}
function contractsPage(){return`<div class="moduleintro"><div><span class="eyebrow">MODULE 01 / CONTRACT INTELLIGENCE</span><h2>Договор против счёта.</h2><p>Условия, исходный текст и изменения — в одном месте.</p></div>${sim}</div><div class="vendorgrid">${s.contracts.map(c=>`<section class="card contractcard"><div class="cardhead"><span class="tag">${c.id}</span><span class="vendorlogo">${vn(c.vendor).split(' ').map(x=>x[0]).join('')}</span></div><h2>${esc(c.service)}</h2><p>${vn(c.vendor)}</p><div class="contractprice">${money(c.unit)}<small> ${c.currency} / ед.</small></div><div class="contractterms"><div><span>Объём</span><b>${c.qty}</b></div><div><span>Индексация</span><b>≤ ${c.indexMax}%</b></div><div><span>До</span><b>${c.end}</b></div><div><span>Допсоглашений</span><b>${c.amendments.length}</b></div></div><div class="actions"><button class="btn primary" data-readcontract="${c.id}">Прочитать договор</button><button class="btn" data-contract="${c.id}" aria-label="Допсоглашение ${c.id}">＋</button></div><button class="textbtn contractupload" data-uploadcontract="${c.id}">Загрузить текст договора ↗</button></section>`).join('')}</div><input id="contractfile" type="file" accept=".txt,.pdf" hidden><div class="notice" style="margin-top:20px">Извлечение условий — симуляция: подготовленные результаты для демодоговоров и шаблонный разбор загруженного текста. Человек подтверждает поля. Подписанные допсоглашения имеют приоритет.</div>`}
function quoteEvidence(d){let c=s.contracts.find(x=>x.id===d.contract);if(!c)return'';let lines=c.source.split('\n').filter(l=>/2\.1\.|4\.[123]\.|Цена:|Индексация:|Порядок изменения:/.test(l)),a=c.amendments.filter(a=>a.date<=d.date).sort((a,b)=>a.date.localeCompare(b.date)).at(-1);return`<blockquote>${lines.length?lines.map(esc).join('<br>'):'Цитата не извлечена. Сверьте исходный договор.'}</blockquote>${a?`<p>Допсоглашение ${a.date}: цена ${money(a.unit)} ${c.currency}, объём ${a.qty}.</p>`:''}<small>${c.sourceKind==='prepared'?'Демонстрационный договор · симуляция':'Загруженный договор · поля подтверждены человеком'}</small>`}
function stageBind(){document.documentElement.dataset.theme=theme;$('#theme').onclick=()=>{theme=theme==='dark'?'light':'dark';localStorage.setItem('tejam-theme',theme);render()};let nav=document.createElement('nav');nav.className='bottomnav';nav.setAttribute('aria-label','Мобильная навигация');nav.innerHTML=[['overview','Обзор'],['checks','Проверки'],['recovery','Возврат'],['contracts','Договоры']].map(([id,t])=>`<button data-mobile="${id}" class="${page===id?'active':''}">${icon(id)}${t}</button>`).join('')+'<button id="mobilemore"><span>☰</span>Ещё</button>';$('#app').append(nav);nav.querySelectorAll('[data-mobile]').forEach(b=>b.onclick=()=>{page=b.dataset.mobile;render();window.scrollTo(0,0)});$('#mobilemore').onclick=()=>{$('aside').classList.toggle('open');if(!$('aside .drawerclose')){let b=document.createElement('button');b.className='drawerclose';b.textContent='Закрыть ×';b.onclick=()=>$('aside').classList.remove('open');$('aside').append(b)}};
 document.querySelectorAll('[data-chart]').forEach(p=>{let choose=()=>{$('#chartline').setAttribute('x1',p.dataset.x);$('#chartline').setAttribute('x2',p.dataset.x);$('#chartdot').setAttribute('cx',p.dataset.x);$('#chartdot').setAttribute('cy',p.dataset.y);$('#charttip').innerHTML=`<small>${+p.dataset.chart+1} · ${p.dataset.month}</small><b>${money(+p.dataset.value)} UZS</b>`};p.onmouseenter=choose;p.onfocus=choose;p.onclick=choose;p.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')choose()}});
 document.querySelectorAll('[data-readcontract]').forEach(b=>b.onclick=()=>readContract(b.dataset.readcontract));document.querySelectorAll('[data-uploadcontract]').forEach(b=>b.onclick=()=>{contractTarget=b.dataset.uploadcontract;$('#contractfile').value='';$('#contractfile').click()});if($('#contractfile'))$('#contractfile').onchange=e=>uploadContract(e.target.files[0],contractTarget);
 document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>claimModal(b.dataset.claim));document.querySelectorAll('[data-recovery]').forEach(select=>select.onchange=()=>{let r=recoveries(s,check(s)).find(x=>x.id===select.dataset.recovery);if(!r)return render();let status=select.value;select.value=r.status;if(status!=='found'&&!r.confirmed){toast('Сначала подтвердите денежный сигнал с комментарием');return}modal(`<h2>Изменение стадии · ${r.id}</h2><p>${{found:'Найдено',sent:'Претензия отправлена',returned:'Возвращено'}[status]} · ${money(r.amount)} ${r.currency}</p><p>${status==='returned'?'Подтвердите получение полной суммы номером платёжного документа. Частичные возвраты пока не поддерживаются.':status==='sent'?'Укажите дату и канал фактической отправки. Приложение не отправляет претензии.':'Укажите причину возврата к начальной стадии.'}</p><textarea id="recovery-note" aria-label="Основание смены стадии" placeholder="Документ, дата, комментарий"></textarea><div class="actions"><button id="save-recovery" class="btn primary">Сохранить отметку</button></div>`);$('#save-recovery').onclick=()=>{let note=$('#recovery-note').value.trim();if(!note)return toast('Укажите основание');s.recoveries[r.id]={status,fingerprint:r.fingerprint,note};log('Возврат: '+{found:'найдено',sent:'претензия отправлена',returned:'возвращено'}[status],r.id,`${money(r.amount)} ${r.currency} · ${note}`);$('#modal').close();render()}});
 document.querySelectorAll('.tablewrap tbody tr td:first-child').forEach(td=>{let title=td.querySelector('strong');if(title){let badge=document.createElement('span');badge.className='tableavatar';badge.textContent=title.textContent.split(' ').map(w=>w[0]).slice(0,2).join('');td.prepend(badge)}});$('#assistantroot').innerHTML='';}
function readContract(id,lang='ru'){let c=s.contracts.find(x=>x.id===id),source=lang==='uz'?c.sourceUz:c.source,fields=[['Цена',`${money(c.unit)} ${c.currency}`],['Объём',c.qty],['Срок',`${c.start} → ${c.end}`],['Индексация',`${c.indexMax}% с ${c.indexDate}`],['Штраф',`${c.penalty}% / день`],['Изменение тарифа',c.changeOrder]];modal(`<div class="cardhead"><div><span class="eyebrow">${id} / CONTRACT READER</span><h2>${esc(c.service)}</h2></div>${sim}</div><p>Подготовленные условия демодоговора или подтверждённые человеком поля загруженного текста. Языковая модель не подключена.</p><div class="actions contractlangs"><button class="btn ${lang==='ru'?'primary':''}" id="contract-ru">Русский</button>${c.sourceUz?`<button class="btn ${lang==='uz'?'primary':''}" id="contract-uz">O‘zbekcha</button>`:''}<button class="btn" id="export-contract">Экспорт текста</button></div><div class="readergrid"><section><h3>Исходный текст</h3><div class="sourcepaper">${source.split('\n').map(l=>`<p>${/2\.[12]\.|3\.[12]\.|4\.[123]\.|5\.1\.|narxi|Indeksatsiya|muddati|penya|Цена:|Объём:|Индексация:|Начало:|Окончание:|Штраф:/i.test(l)?`<mark>${esc(l)}</mark>`:esc(l)}</p>`).join('')}</div></section><section><h3>Извлечённые условия</h3><div class="extracted">${fields.map(([k,v])=>`<div><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div>${c.amendments.length?`<h3 style="margin-top:20px">Допсоглашения</h3>${c.amendments.map(a=>`<p>${a.date}: ${money(a.unit)} ${c.currency}, объём ${a.qty}</p>`).join('')}`:''}</section></div>`);$('#modal').classList.add('wide-modal');$('#contract-ru').onclick=()=>readContract(id,'ru');if($('#contract-uz'))$('#contract-uz').onclick=()=>readContract(id,'uz');$('#export-contract').onclick=()=>download(id+'-'+lang+'.txt',source,'text/plain;charset=utf-8');}
async function readTextFile(file){if(file.size>10*1024*1024)throw Error('Максимум 10 МБ');let ext=file.name.split('.').pop().toLowerCase();if(ext==='txt')return file.text();if(ext!=='pdf')throw Error('Поддерживаются TXT и текстовые PDF');pdfjsLib.GlobalWorkerOptions.workerSrc='assets/pdf.worker.min.js';let pdf=await pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;if(pdf.numPages>30)throw Error('Максимум 30 страниц');let text='';for(let i=1;i<=pdf.numPages;i++){let p=await pdf.getPage(i),items=(await p.getTextContent()).items,y=null;for(let item of items){if(y!==null&&Math.abs(item.transform[5]-y)>2)text+='\n';text+=item.str+' ';y=item.transform[5]}text+='\n'}if(text.trim().length<20)throw Error('Нет текстового слоя. OCR сканов не подключён.');return text;}
async function uploadContract(file,id){if(!file)return;toast('Читаем договор…');try{let source=await readTextFile(file);contractConfirm(id,source,parseContract(source))}catch(e){toast(e.message)}}
function contractConfirm(id,source,p){let c=s.contracts.find(x=>x.id===id);const field=(k,label,type='text')=>`<label>${label}<input name="${k}" type="${type}" value="${esc(p[k]??'')}" required ${type==='number'?'min="0" step="any"':''}></label>`;modal(`<h2>${id} · Проверьте условия</h2>${sim}<p>Шаблонный разбор без LLM. Нераспознанные поля оставлены пустыми. Вы обновляете выбранный договор, сохраняя поставщика и допсоглашения.</p><form id="confirmcontract"><div class="readergrid"><pre class="docpreview">${esc(source)}</pre><div class="formgrid">${field('service','Услуга')}${field('currency','Валюта: UZS, USD, EUR')}${field('unit','Цена за единицу','number')}${field('qty','Объём','number')}${field('tax','Ставка, %','number')}${field('start','Начало','date')}${field('end','Окончание','date')}${field('indexMax','Максимальная индексация, %','number')}${field('indexDate','Дата индексации','date')}${field('penalty','Штраф, % / день','number')}<label class="wide">Порядок изменения тарифа<textarea name="changeOrder" required>${esc(p.changeOrder)}</textarea></label></div></div><label class="confirmcheck"><input type="checkbox" required>Я сверила поля с исходным текстом. Допсоглашения остаются действующими.</label><div class="actions"><button type="submit" class="btn primary">Подтвердить и пересчитать</button></div></form>`);$('#modal').classList.add('wide-modal');$('#confirmcontract').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));for(let k of ['unit','qty','tax','indexMax','penalty'])x[k]=Number(x[k]);x.currency=x.currency.trim().toUpperCase();if(x.unit<=0||x.qty<=0||x.end<x.start||!['UZS','USD','EUR'].includes(x.currency))return toast('Проверьте цену, объём, сроки и валюту');Object.assign(c,x,{source,sourceKind:'uploaded',sourceUz:null});s.decisions={};log('Договор подтверждён после загрузки',id,'Поля проверены человеком; результаты пересчитаны');$('#modal').close();render();toast('Договор обновлён. Проверьте новые сигналы.')};}
function claimText(r,lang){let c=s.contracts.find(c=>c.id===r.d.contract),clause=r.primary.rule==='duplicate'?(c?.source.split('\n').find(l=>/6\.1\.|Повторная оплата/.test(l))||'Пункт о повторной оплате не найден: уточните по договору.'):(c?.source.split('\n').filter(l=>/2\.1\.|4\.[123]\.|Цена:|Индексация:|Порядок изменения:/.test(l)).join('\n')||'Пункт не извлечён: уточните по договору.');if(lang==='uz')return`LOYIHA · yuborilmagan\nKimga: ${vn(r.d.vendor)}\nMavzu: ${r.id} bo‘yicha solishtirish va mablag‘ni qaytarish\n\nHurmatli hamkor,\n${r.id} raqamli, ${r.d.date} sanadagi hisob-faktura (${r.d.period} davri, ${r.d.service}) bo‘yicha tafovut aniqlandi.\nTekshirilayotgan summa: ${money(r.amount)} ${r.currency}.\nAsos: ${r.primary.rule==='duplicate'?'Bir xizmat, davr va summa bo‘yicha takroriy hisob-faktura.':r.primary.rule==='price'?'Hisobdagi narx shartnomada ruxsat etilgan narxdan yuqori.':'Miqdor yoki hisob summasida tafovut.'}\nHisob: ${r.d.qty} × ${r.d.unit}; jami ${r.d.amount} ${r.currency}.\nShartnoma: ${c?.id||'topilmadi'}. Asl band (rus tilida):\n${clause}\n\nIltimos, solishtirishni amalga oshiring. Tafovut tasdiqlansa, ${money(r.amount)} ${r.currency} summani qaytaring yoki tuzatish hujjatini taqdim eting. Ushbu signal firibgarlikni anglatmaydi.\nIlovalar: hisob-faktura va shartnoma (qo‘shilishi kerak).\nJo‘natuvchi va rekvizitlar: [to‘ldiring].`;return`ЧЕРНОВИК · не отправлено\nКому: ${vn(r.d.vendor)}\nТема: сверка и возврат по счёту ${r.id}\n\nУважаемые коллеги,\nПри сверке счёта ${r.id} от ${r.d.date} за период ${r.d.period} (${r.d.service}) обнаружено расхождение на ${money(r.amount)} ${r.currency}.\nОснование: ${r.primary.detail}\nДоговор: ${c?.id||'не найден'}. Цитата условия:\n${clause}\n\nПросим провести сверку и, при подтверждении расхождения, вернуть ${money(r.amount)} ${r.currency} либо предоставить корректирующий документ и пояснение. Сигнал не означает мошенничество.\nПриложения: счёт и договор (добавить перед отправкой).\nОтправитель и реквизиты: [заполнить].`}
function claimModal(id,lang='ru'){let r=recoveries(s,check(s)).find(x=>x.id===id);if(!r)return toast('Основание больше не активно');modal(`<h2>Претензия · ${id}</h2>${sim}<p>Черновик по данным случая. Проверьте основания и приложения. Отправка из приложения не выполняется.</p><div class="actions"><button id="claim-ru" class="btn ${lang==='ru'?'primary':''}">Русский</button><button id="claim-uz" class="btn ${lang==='uz'?'primary':''}">O‘zbekcha</button></div><textarea id="claimtext" class="claimtext" aria-label="Текст претензии">${esc(claimText(r,lang))}</textarea><div class="actions"><button id="claim-copy" class="btn">Копировать</button><button id="claim-export" class="btn primary">Экспорт TXT</button></div>`);$('#claim-ru').onclick=()=>claimModal(id,'ru');$('#claim-uz').onclick=()=>claimModal(id,'uz');$('#claim-copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#claimtext').value);toast('Текст скопирован')}catch{$('#claimtext').select();toast('Выделен текст: нажмите Ctrl/Cmd+C')}};$('#claim-export').onclick=()=>{download(`claim-${id}-${lang}.txt`,$('#claimtext').value,'text/plain;charset=utf-8');log('Экспорт черновика претензии',id,lang)}}
function assistantAnswer(q){let fs=check(s),rs=recoveries(s,fs),lower=q.toLowerCase(),id=q.match(/INV-\d+|TEST-[\w-]+/i)?.[0]?.toUpperCase(),text='',links=[];if(id){let d=s.invoices.find(x=>x.id===id);if(!d)return{text:`Счёт ${id} не найден в демоданных.`,links};let signals=fs.filter(f=>f.invoice===id);text=`${id} · ${vn(d.vendor)} · ${money(d.amount)} ${d.currency}. ${signals.length?signals.map(f=>`${f.title}: ${f.detail} Статус: ${{open:'ожидает проверки',confirmed:'подтверждён',dismissed:'снят',requested:'запрошены данные'}[f.status]}.`).join('\n\n'):'По включённым правилам сигналов нет.'}`;links=signals.map(f=>({type:'case',id:f.id,label:f.title}));links.push({type:'invoice',id,label:'Открыть '+id})}else if(/возврат|вернут/.test(lower)){text=`По оплаченным счетам найдено к возврату ${money(sumUZS(rs))} UZS, включая все стадии. Отмечено возвращённым ${money(sumUZS(rs.filter(r=>r.status==='returned')))} UZS. Это оценка, не подтверждение платежа. На один счёт берём максимальное расхождение; валюты не складываем.`;links=[{type:'page',id:'recovery',label:'Возврат средств'},...rs.slice(0,4).map(r=>({type:'case',id:r.primary.id,label:r.id+' · '+money(r.amount)+' '+r.currency}))]}else if(/аренд/.test(lower)){let ids=s.invoices.filter(d=>/аренд/i.test(d.service)||d.contract==='C-105').map(d=>d.id),signals=fs.filter(f=>ids.includes(f.invoice)&&f.status!=='dismissed');text=signals.length?signals.map(f=>`${f.invoice}: ${f.title}. ${f.detail}`).join('\n\n'):'Активных сигналов по аренде нет. Проверьте включённые правила.';links=signals.map(f=>({type:'case',id:f.id,label:f.invoice+' · '+f.title}));links.push({type:'contract',id:'C-105',label:'Условия Urban Office'})}else if(/риск|опасн/.test(lower)){let f=fs.filter(f=>f.status!=='dismissed').sort((a,b)=>({high:3,medium:2,low:1}[b.severity]-{high:3,medium:2,low:1}[a.severity])||(b.currency==='UZS'?b.exposure:0)-(a.currency==='UZS'?a.exposure:0))[0];text=f?`${f.invoice}: ${f.title}. ${f.detail} Приоритет выбран по уровню правила, затем по сумме расхождения в UZS. Это не вероятность мошенничества.`:'Активных сигналов нет.';if(f)links=[{type:'case',id:f.id,label:'Разобрать '+f.invoice}]}else text='Для этого вопроса нет подготовленного ответа. Могу показать суммы к возврату, объяснить конкретный счёт (например INV-003), сигналы по аренде или приоритетный риск. Данные вне демо мне недоступны.';return{text,links}}
function renderChat(){let root=$('#assistantroot');root.innerHTML=`<a class="telegramfab" href="${esc(TELEGRAM_BOT_URL)}" target="_blank" rel="noopener" aria-label="Открыть Telegram-бота @tejam_invoice_bot">${icon('telegram')}<span>Telegram</span></a><button class="chatfab ${chatOpen?'isopen':''}" id="chat-toggle" aria-label="${chatOpen?'Закрыть помощника':'Открыть помощника'}" aria-expanded="${chatOpen}">${chatOpen?'×':icon('chat')}</button>${chatOpen?`<section class="chatpanel" role="dialog" aria-label="AI Assistant"><div class="chatheader"><div><span class="eyebrow">TEJAM INTELLIGENCE</span><h2>AI Assistant</h2></div><button id="chat-close" aria-label="Свернуть помощника">×</button></div><div class="chatmessages" id="chatmessages"><div class="chatmessage assistant">${sim}<br>Помогу разобраться в счетах и договорах. Отвечаю по шаблонам на текущих данных демо, без языковой модели.</div>${chatMessages.map(m=>`<div class="chatmessage ${m.role}">${m.role==='assistant'?sim+'<br>':''}${esc(m.text).replaceAll('\n','<br>')}${m.links?.length?`<div class="chatlinks">${m.links.map(l=>`<button data-chatlink="${l.type}" data-id="${esc(l.id)}">${esc(l.label)} ↗</button>`).join('')}</div>`:''}</div>`).join('')}</div><div class="quicks">${['Что найдено к возврату?','Самый рискованный счёт','Объясни сигнал по аренде'].map(q=>`<button data-quick="${q}">${q}</button>`).join('')}</div><form id="chatform"><input id="chatinput" aria-label="Сообщение помощнику" placeholder="Почему сигнал по INV-003?" maxlength="500" required><button aria-label="Отправить сообщение">↑</button></form><div class="telegramrow"><div id="telegramqr" aria-label="QR-код ссылки Telegram"></div><div><a href="${esc(TELEGRAM_BOT_URL)}" target="_blank" rel="noopener">Открыть в Telegram ↗</a><strong class="realbot">Реальный бот: @${esc(new URL(TELEGRAM_BOT_URL).pathname.slice(1))}</strong><small>Бот проверяет счёт до внесения в бюджет и помогает разобраться, что произошло.</small></div></div></section>`:''}`;$('#chat-toggle').onclick=()=>{chatOpen=!chatOpen;renderChat()};if(!chatOpen)return;$('#chat-close').onclick=()=>{chatOpen=false;renderChat()};new QRCode($('#telegramqr'),{text:TELEGRAM_BOT_URL,width:80,height:80,colorDark:'#17120f',colorLight:'#fff',correctLevel:QRCode.CorrectLevel.M});const send=q=>{chatMessages.push({role:'user',text:q},{role:'assistant',...assistantAnswer(q)});renderChat();$('#chatmessages').scrollTop=$('#chatmessages').scrollHeight;$('#chatinput').focus()};$('#chatform').onsubmit=e=>{e.preventDefault();let q=$('#chatinput').value.trim();if(q)send(q)};document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>send(b.dataset.quick));document.querySelectorAll('[data-chatlink]').forEach(b=>b.onclick=()=>{let id=b.dataset.id,type=b.dataset.chatlink;chatOpen=false;renderChat();if(type==='case')caseModal(id);if(type==='invoice')invoiceForm(s.invoices.find(d=>d.id===id));if(type==='contract')readContract(id);if(type==='page'){page=id;render()}});}
render();
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.data?.type==='tejam-page'&&['checks','documents','contracts','vendors','recovery','rules','demo'].includes(e.data.page)){page=e.data.page;render()}});
